<?php defined( 'ABSPATH' ) || exit; $payload = $result['data'] ?? []; $systems = $payload['systems'] ?? $payload['data'] ?? []; ?>
<section class="cyberfort-ai-register" aria-live="polite">
<?php if ( ! empty( $payload['organisation_name'] ) ) : ?><h1 class="cyberfort-ai-register__title"><?php echo esc_html( $payload['organisation_name'] ); ?></h1><?php endif; ?>
<?php if ( ! empty( $payload['introduction'] ) ) : ?><p class="cyberfort-ai-register__introduction"><?php echo esc_html( $payload['introduction'] ); ?></p><?php endif; ?>
<?php if ( empty( $result['error'] ) && ( $options['search'] || $options['filters'] ) ) : ?><form class="cyberfort-ai-register__filters" method="get"><label><?php esc_html_e( 'Search AI systems', 'cyberfort-ai-register' ); ?><input type="search" name="cfair_search" value="<?php echo esc_attr( $params['search'] ); ?>"></label><?php if ( $options['filters'] ) : ?><label><?php esc_html_e( 'Risk tier', 'cyberfort-ai-register' ); ?><select name="cfair_risk"><option value=""><?php esc_html_e( 'All risk tiers', 'cyberfort-ai-register' ); ?></option><?php foreach ( [ 'minimal', 'limited', 'high', 'unacceptable' ] as $risk ) : ?><option value="<?php echo esc_attr( $risk ); ?>" <?php selected( $params['risk_tier'], $risk ); ?>><?php echo esc_html( ucfirst( $risk ) ); ?></option><?php endforeach; ?></select></label><?php endif; ?><button type="submit"><?php esc_html_e( 'Apply filters', 'cyberfort-ai-register' ); ?></button></form><?php endif; ?>
<?php if ( ! empty( $result['error'] ) ) : ?><p class="cyberfort-ai-register__error"><?php esc_html_e( 'The public AI systems register is temporarily unavailable. Please try again later.', 'cyberfort-ai-register' ); ?></p><?php elseif ( empty( $systems ) ) : ?><p class="cyberfort-ai-register__empty"><?php esc_html_e( 'No AI systems have currently been published in this register.', 'cyberfort-ai-register' ); ?></p><?php else : ?><div class="cyberfort-ai-register__systems cyberfort-ai-register__systems--<?php echo esc_attr( $options['layout'] ); ?>"><?php foreach ( $systems as $system ) : if ( ! is_array( $system ) ) continue; ?><article class="cyberfort-ai-register__system-card"><h2><a href="<?php echo esc_url( trailingslashit( home_url( get_option( 'cfair_base_slug', 'ai-register' ) ) ) . rawurlencode( (string) ( $system['reference'] ?? '' ) ) ); ?>"><?php echo esc_html( $system['name'] ?? $system['reference'] ?? '' ); ?></a></h2><p class="cyberfort-ai-register__reference"><?php echo esc_html( $system['reference'] ?? '' ); ?></p><?php if ( ! empty( $system['purpose'] ) ) : ?><p><?php echo esc_html( $system['purpose'] ); ?></p><?php endif; ?><?php if ( ! empty( $system['risk_tier'] ) ) : ?><span class="cyberfort-ai-register__risk-badge"><?php echo esc_html( $system['risk_tier'] ); ?></span><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?>
</section>
